		description.appendText("the same day as " + describe(expected.apply(zone)));
	}

	@Override
	public TemporalMatcher<T> atZone(ZoneId zone) {
		return new IsSameDay<>(converter, expected, Optional.of(zone), locale);
	}

    @Override
